import { Button, Chip, Dialog, DialogActions, DialogContent, DialogTitle, TextField, Typography } from '@mui/material'
import React from 'react'
import { useDispatch, useSelector } from 'react-redux'
import MSTextField from '../../customTheme/textField/MSTextField'
import { UserCredits } from '../../redux/fetchUsersSlice'
import { useSnackbar } from "../../hook/useSnackbar";
import { isMobile } from 'react-device-detect'
import  Crossicon from "../../assests/homeScreen/crossicon.svg";
export default function CreditDialog(props) {
    const [credits, setCredits] = React.useState(0)
    const [chips, setChips] = React.useState([
        { label: '100', value: 100 }, { label: '500', value: 500 }, { label: '1000', value: 1000 },
        { label: '1500', value: 1500 }, { label: '5000', value: 5000 }, { label: '10000', value: 10000 },
    ])
    const [selectedChip, setSelectedChip] = React.useState(null)
    const dispatch = useDispatch()
    const { displaySnackbar } = useSnackbar();
    const { accessToken, refreshToken, tokenExpiry, userRole } = useSelector((state) => state.login)
    
    // action: "add" for adding credits, "remove" for removing credits
    // Supports negative values: entering -300 with "Add" will reduce 300 credits
    const handleAction = (isRemove) => {
        const creditValue = parseInt(credits) || 0;
        
        if (creditValue === 0) {
            displaySnackbar({ message: 'Please enter a valid credit amount' });
            return;
        }
        
        // Determine the actual action based on value sign and button clicked
        // If user enters negative value with Add button, treat as Remove
        // If user enters positive value with Remove button, treat as Remove
        let actualAction = isRemove ? "remove" : "add";
        let creditAmount = Math.abs(creditValue);
        
        // If negative value entered with Add button, switch to remove action
        if (!isRemove && creditValue < 0) {
            actualAction = "remove";
        }
        // If negative value entered with Remove button, switch to add action  
        if (isRemove && creditValue < 0) {
            actualAction = "add";
        }
        
        let data = {
            userId: props.params.row.userId,
            credits: creditAmount,
            action: actualAction
        }
        
        let header = {
            "Content-Type": "application/json",
            'Accept': 'application/json',
            "Authorization": `Bearer ${accessToken}`
        }
        dispatch(UserCredits({
            headers : header,
            body : data
        })).then((res) => {
            if (res.payload?.success === false) {
                displaySnackbar({ message: res.payload?.message || 'Operation failed' });
            } else {
                props.params.row?.handleFetchUserData()
                const actionWord = actualAction === 'remove' ? 'removed from' : 'added to';
                displaySnackbar({ message: `${creditAmount} credits ${actionWord} user successfully` })
                props.handleClose();
            }
        }).catch((err) => {
            displaySnackbar({ message: 'Failed to update credits' });
        })
    }
    return (
        <>
          {/* <Crossicon   className='loginCloseModal'/>   */}
        <Dialog open={props.open} onClose={props.handleClose} PaperProps={{
            style: {
                width: '50vw',
            }
        }}>
         <div className='closeCreditModal' style={{display:'flex',flexDirection:'row',alignItems:'center',justifyContent:'flex-end'}}>
             <img src={Crossicon}  onClick={() => props.handleClose()}/>
            </div>
            <DialogTitle >Manage Image Credits 
            {/* <div className='closeCreditModal' style={{display:'flex',flexDirection:'row',alignItems:'center',justifyContent:'flex-end'}}>
             <img src={Crossicon}  onClick={() => props.handleClose()}/>
            </div> */}
             </DialogTitle>
            <DialogContent style={{cursor:'pointer'}}>
                <MSTextField
                    id="credits" type="number" placeholder="Enter Number of credits to add or remove" value={credits !== 0 ? credits : null}
                    label="* Credits" onChange={(e) => setCredits(e.target.value)} fieldName="credits"
                />
                <div style={{ display: 'flex', gap: 10, marginTop: 20, flexDirection: isMobile ? 'column' : 'row' }}>
                    {chips.map((k, i) => <div onClick={() => {
                        setSelectedChip(k.value)
                        setCredits(k.value)
                    }}
                        style={{
                            padding: 5,
                            border: '1px solid #B3DAFF',
                            borderRadius: 20,
                            minWidth: 50,
                        }}>
                        <Typography textAlign={'center'}>{k.label}</Typography>
                    </div>)}
                </div>
            </DialogContent>
            <DialogActions>
                <Button fullWidth
                    onClick={() => handleAction(false)}
                    sx={{
                        ':hover': {
                            border: '2px solid #B3DAFF !important',
                            backgroundColor: 'white !important'
                        }
                    }}
                    style={{
                        backgroundColor: '#B3DAFF',
                        borderRadius: '8px'
                    }}>Add</Button>
                <Button fullWidth
                    onClick={() => handleAction(true)}
                    sx={{
                        ':hover': {
                            border: '2px solid #B3DAFF !important',
                            backgroundColor: 'white !important'
                        }
                    }}
                    style={{
                        backgroundColor: '#B3DAFF',
                        borderRadius: '8px'
                    }}>Remove</Button>
            </DialogActions>
        </Dialog>
        </>
    )
}