import React from 'react';
import { ScrollMenu, VisibilityContext } from "react-horizontal-scrolling-menu";
import { LeftArrow, RightArrow } from '../../uicomponent/filter/Arrow';
import useDrag from '../../customTheme/signUpMenu/useDrag';
import "../../customTheme/signUpMenu/hideScrollBar.css";
import "./filter.css";
import { filterConfig, menuNameMap } from './constant/filterData';
import { useLocation } from "react-router-dom";

const StructureFilter = (props) => {
    let location = useLocation()
    const [wholeStructList, setWholeStructList] = React.useState([])
    const [structureList, setStructureList] = React.useState([])
    const [selectedCard, setSelectedCard] = React.useState(null)
    const [currentSection, setCurrentSection] = React.useState(null)
    
    // Parse the current URL to determine section
    React.useEffect(() => {
        const pathParts = location.pathname.toLowerCase().split('/').filter(ele => ele && ele !== 'views');
        
        // Determine current section from URL
        let section = null;
        
        // Check for imagebank pages: /views/academic/imagebank or /views/sections/image-bank
        if (pathParts.includes('imagebank') || pathParts.includes('image-bank')) {
            section = 'imagebank';
        }
        // Check for One Click sections: /views/sections/comics, /views/sections/rhymes, etc.
        else if (pathParts.includes('sections')) {
            const sectionsIndex = pathParts.indexOf('sections');
            if (sectionsIndex !== -1 && pathParts[sectionsIndex + 1]) {
                section = pathParts[sectionsIndex + 1];
            }
        }
        // Other academic sub-pages (not class pages - those use AcademicFilter)
        else if (pathParts.includes('academic')) {
            const academicIndex = pathParts.indexOf('academic');
            if (academicIndex !== -1 && pathParts[academicIndex + 1]) {
                const subPage = pathParts[academicIndex + 1];
                // Only handle non-class academic pages
                if (subPage !== 'class') {
                    section = subPage;
                }
            }
        }
        
        setCurrentSection(section);
        
        // Get filters for this section
        const config = filterConfig[section];
        if (config) {
            setStructureList(config.filters);
            setWholeStructList(config.filters);
        } else {
            setStructureList([]);
            setWholeStructList([]);
        }
        
        // Reset selection when section changes
        setSelectedCard(null);
    }, [location.pathname]);
    
    const { dragStart, dragStop, dragMove, dragging } = useDrag();
    const handleDrag = ({ scrollContainer }) => (e) => dragMove(e, (posDiff) => {
        if (scrollContainer.current) {
            scrollContainer.current.scrollLeft += posDiff;
        }
    });
    
    // Build the correct API path based on current section and selected filter
    const buildApiPath = (filterTitle) => {
        const config = filterConfig[currentSection];
        
        if (!config) return null;
        
        let apiPath = '';
        const menuName = menuNameMap[currentSection] || currentSection?.toUpperCase() || '';
        
        switch (config.type) {
            case 'imagebank': {
                // Image Bank: one_click_resource_centre/image bank/ANIMALS
                apiPath = 'one_click_resource_centre/image bank';
                if (filterTitle) {
                    apiPath += `/${filterTitle}`;
                }
                break;
            }
            
            case 'oneclick':
            case 'oneclick-class':
            case 'oneclick-category': {
                // One Click sections: one_click_resource_centre/comics/ADVENTURE
                apiPath = `one_click_resource_centre/${menuName.toLowerCase()}`;
                if (filterTitle) {
                    apiPath += `/${filterTitle}`;
                }
                break;
            }
            
            default:
                apiPath = currentSection || '';
                if (filterTitle) {
                    apiPath += `/${filterTitle}`;
                }
        }
        
        return apiPath;
    };
    
    const handleItemClick = (data) => {
        if (dragging) {
            return false;
        }
        
        // If clicking on already selected item, deselect and show all
        if (selectedCard === data.title) {
            setSelectedCard(null);
            const basePath = buildApiPath(null);
            if (basePath) {
                props.loadImages(basePath);
            }
            return;
        }
        
        // Select new item
        setSelectedCard(data.title);
        
        // Build and load path
        const apiPath = buildApiPath(data.title);
        if (apiPath) {
            props.loadImages(apiPath);
        }
    };
    
    const handleSelected = (data) => {
        return selectedCard === data.title;
    };
    
    // Don't render if no filters available
    if (structureList.length === 0) {
        return null;
    }
    
    // Don't render for academic/class pages - they use AcademicFilter blue pane instead
    // This prevents duplicate filters (blue pane + white bar) when browsing CLASS pages
    // Check both currentSection config AND URL directly for class-related paths
    const config = filterConfig[currentSection];
    const pathLower = location.pathname.toLowerCase();
    const isClassPage = pathLower.includes('/class/') || pathLower.includes('/class-') || 
                        pathLower.endsWith('/class') || pathLower.includes('/nursery') ||
                        pathLower.includes('/lkg') || pathLower.includes('/ukg');
    
    if (isClassPage) {
        return null;
    }
    
    if (config && (config.type === 'academic' || config.type === 'academic-class')) {
        return null;
    }
    
    return (
        <div className="structureFilterContainer">
            <div className="structureFilterSelector">
                <ScrollMenu
                    onMouseDown={() => dragStart}
                    LeftArrow={LeftArrow}
                    RightArrow={RightArrow}
                    onMouseUp={() => dragStop}
                    onMouseMove={handleDrag}
                    style={{ width: '0px !important' }}
                >
                    {structureList.map((k, i) => (
                        <StructureFilterCard
                            itemId={k.title}
                            title={k.title}
                            key={`${k.title}-${i}`}
                            onClick={() => handleItemClick(k)}
                            selected={handleSelected(k)}
                        />
                    ))}
                </ScrollMenu>
            </div>
        </div>
    );
};

function StructureFilterCard({ onClick, selected, title }) {
    const visibility = React.useContext(VisibilityContext);
    return (
        <div onClick={() => onClick(visibility)} style={{ width: 'max-content' }} tabIndex={0}>
            <p className={selected ? "structureFilterItemActive" : "structureFilterItem"} unselectable="on">
                {title}
            </p>
        </div>
    );
}

export default StructureFilter;
