/**
 * Validate a single character input
 * @param {string} char - The character to validate
 * @param {string} fieldName - The field name to get validation rules
 * @returns {boolean} - Whether the character is valid
 */
export const validateCharacter = (char, fieldName) => {
    const config = FIELD_VALIDATION_CONFIG[fieldName];
    if (!config) return true;
    
    // Allow spaces for certain fields
    if (char === ' ') {
        return config.allowSpaces !== false;
    }
    
    // Allow + for mobile numbers
    if (char === '+' && config.allowPlus) {
        return true;
    }
    
    // For email, allow all characters during typing (validate on blur)
    if (config.validateOnBlur) {
        return true;
    }
    
    return config.pattern.test(char);
};

/**
 * Validate entire field value
 * @param {string} value - The value to validate
 * @param {string} fieldName - The field name to get validation rules
 * @returns {object} - { isValid: boolean, errorMessage: string }
 */
export const validateField = (value, fieldName) => {
    const config = FIELD_VALIDATION_CONFIG[fieldName];
    if (!config) return { isValid: true, errorMessage: '' };
    
    if (!value) return { isValid: true, errorMessage: '' };
    
    // Check max length
    if (config.maxLength && value.length > config.maxLength) {
        return { 
            isValid: false, 
            errorMessage: `Maximum ${config.maxLength} characters allowed` 
        };
    }
    
    // Check min length (for passwords)
    if (config.minLength && value.length < config.minLength && value.length > 0) {
        return { 
            isValid: false, 
            errorMessage: `Minimum ${config.minLength} characters required` 
        };
    }
    
    // For email, validate format only on blur or submit
    if (fieldName === 'emailId' || fieldName === 'email') {
        if (!config.pattern.test(value)) {
            return { isValid: false, errorMessage: config.errorMessage };
        }
    }
    
    return { isValid: true, errorMessage: '' };
};

/**
 * Filter input value based on field validation rules
 * @param {string} value - The input value
 * @param {string} fieldName - The field name to get validation rules
 * @returns {string} - Filtered value containing only valid characters
 */
export const filterInput = (value, fieldName) => {
    const config = FIELD_VALIDATION_CONFIG[fieldName];
    if (!config) return value;
    
    // Check max length
    let filteredValue = value;
    if (config.maxLength && filteredValue.length > config.maxLength) {
        filteredValue = filteredValue.slice(0, config.maxLength);
    }
    
    // For mobile numbers, allow + at the start and only numbers
    if (fieldName === 'mobileNumber') {
        let result = '';
        for (let i = 0; i < filteredValue.length; i++) {
            const char = filteredValue[i];
            if (i === 0 && char === '+') {
                result += char;
            } else if (/[0-9]/.test(char)) {
                result += char;
            }
        }
        return result.slice(0, config.maxLength);
    }
    
    // For email, allow all characters (validate format separately)
    if (fieldName === 'emailId' || fieldName === 'email') {
        return filteredValue;
    }
    
    // For other fields, filter based on pattern
    let result = '';
    for (const char of filteredValue) {
        if (char === ' ' && config.allowSpaces !== false) {
            result += char;
        } else if (config.pattern && config.pattern.test(char)) {
            result += char;
        }
    }
    
    return result;
};

/**
 * Get max length for a field
 * @param {string} fieldName - The field name
 * @returns {number} - Max length or undefined
 */
export const getMaxLength = (fieldName) => {
    const config = FIELD_VALIDATION_CONFIG[fieldName];
    return config?.maxLength;
};

/**
 * Get input type for a field
 * @param {string} fieldName - The field name
 * @returns {string} - Input type (text, email, tel, etc.)
 */
export const getInputType = (fieldName) => {
    if (fieldName === 'emailId' || fieldName === 'email') return 'email';
    if (fieldName === 'mobileNumber') return 'tel';
    if (fieldName === 'password' || fieldName === 'confirmPassword') return 'password';
    if (fieldName === 'postalCode') return 'tel';
    return 'text';
};

export default {
    VALIDATION_PATTERNS,
    FIELD_VALIDATION_CONFIG,
    validateCharacter,
    validateField,
    filterInput,
    getMaxLength,
    getInputType
};
