import React, { useState } from 'react'
import { TextField, InputAdornment, FormHelperText } from '@mui/material'

// Max lengths for fields
const maxLengths = {
    name: 50,
    schoolName: 40,
    schoolCode: 20,
    principalName: 40,
    mobileNumber: 13,
    emailId: 60,
    email: 60,
    address: 100,
    city: 30,
    state: 30,
    postalCode: 6,
    password: 15,
    confirmPassword: 15,
    userName: 50,
    className: 30,
    rollNumber: 20,
    sectionName: 20,
    section: 20,
    fatherName: 50,
    parentName: 50,
    teacherCode: 20,
    studentCode: 20,
};

const MSTextField = (props) => {
    const [error, setError] = useState('');
    const [internalValue, setInternalValue] = useState('');
    
    const maxLength = maxLengths[props.fieldName] || 200;
    
    // Use props.value if provided (controlled), otherwise use internal state (uncontrolled)
    const isControlled = props.value !== undefined;
    const displayValue = isControlled ? props.value : internalValue;
    
    const handleChange = (e) => {
        let value = e.target.value;
        
        // Only enforce maxLength
        if (maxLength && value.length > maxLength) {
            value = value.slice(0, maxLength);
        }
        
        // Clear any error
        if (error) setError('');
        
        // Update internal state for uncontrolled mode
        if (!isControlled) {
            setInternalValue(value);
        }
        
        // Call parent onChange
        if (props.onChange) {
            const modifiedEvent = { 
                target: { value },
                preventDefault: () => {}  // Add preventDefault for forms that call it
            };
            if (props.fieldName) {
                props.onChange(modifiedEvent, props.fieldName);
            } else {
                props.onChange(modifiedEvent);
            }
        }
    };
    
    const handleBlur = () => {
        const value = displayValue;
        
        // Email validation on blur
        if ((props.fieldName === 'emailId' || props.fieldName === 'email' || props.type === 'email') && value) {
            const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
            if (!emailRegex.test(value)) {
                setError('Enter a valid email address');
                return;
            }
        }
        
        // Password validation on blur
        if ((props.fieldName === 'password' || props.fieldName === 'confirmPassword' || props.type === 'password') && value) {
            if (value.length > 15) {
                setError('Password must not exceed 15 characters');
                return;
            }
            if (!/[A-Z]/.test(value)) {
                setError('Password must contain at least one capital letter');
                return;
            }
        }
        
        setError('');
    };
    
    return (
        <div style={[{
            display: 'flex',
            flexDirection: 'column'
        }, props.style].reduce((acc, curr) => Object.assign(acc, curr), {})}>
            <label htmlFor={props.id}>{props.label}</label>
            {props.label ? 
            <>
                <TextField 
                    type={props.type} 
                    id={props.id} 
                    disabled={props.disabled}
                    value={displayValue} 
                    style={props.style}
                    onChange={handleChange}
                    onBlur={handleBlur}
                    error={!!error}
                    inputProps={{
                        maxLength: maxLength,
                        autoComplete: props.type === 'password' ? 'new-password' : 'off'
                    }}
                    InputProps={{
                        startAdornment: props.fieldName === "schoolCode" || props.fieldName === "teacherCode" ? 
                        <InputAdornment position="start">{props.fieldName === "schoolCode" ? "SC" : "TR"} </InputAdornment> : null 
                    }}
                    sx={{
                        '& input::placeholder': {
                            color: '#aaa',
                            opacity: 0.6,
                            fontStyle: 'italic',
                        },
                    }}
                    fullWidth 
                    placeholder={props.placeholder} 
                    size='small' 
                />
                {error && <FormHelperText error>{error}</FormHelperText>}
            </> : null }
        </div>
    )
}
export default MSTextField
